match RemoteAiStudioServer::start(context.clone()) {
    Ok((server, requests)) => {
        #[cfg(feature = "visual-validation")]
        if let Some(path) =
            std::env::var_os("GAMEENGINE_REMOTE_AI_STUDIO_VISUAL_URL_TO")
            && let Err(error) = fs::write(PathBuf::from(path), server.companion_url())
        {
            self.status = Some(format!(
                "Remote AI Studio visual-validation URL could not be published: {error}"
            ));
        }
        self.remote_server = Some(server);
        self.remote_requests = Some(requests);
    }
